package main

import (
	"context"
	"flag"
	"log"
	"net"
	"strings"
	"time"

	"google.golang.org/grpc"

	pb "github.com/siddharth-roy27/distributed-kv-store/proto/kv"
	raftpb "github.com/siddharth-roy27/distributed-kv-store/proto/raft"
	"github.com/siddharth-roy27/distributed-kv-store/internal/raft"
)

// In-memory KV store (simple)
var store = make(map[string]string)

type server struct {
	pb.UnimplementedKVServer
	raftNode *raft.RaftNode
}

func (s *server) Get(ctx context.Context, req *pb.GetRequest) (*pb.GetResponse, error) {
	value, ok := store[req.Key]
	return &pb.GetResponse{Value: value, Found: ok}, nil
}

func (s *server) Set(ctx context.Context, req *pb.SetRequest) (*pb.SetResponse, error) {
	// TODO: route via leader. For now we write locally (useful for testing)
	store[req.Key] = req.Value
	return &pb.SetResponse{Success: true}, nil
}

func main() {
	// parse flags
	id := flag.String("id", "node1", "node id")
	port := flag.Int("port", 50051, "gRPC port to listen on")
	peers := flag.String("peers", "", "comma-separated list of peer addresses (host:port)")
	flag.Parse()

	peerAddrs := []string{}
	if *peers != "" {
		for _, p := range strings.Split(*peers, ",") {
			trim := strings.TrimSpace(p)
			if trim != "" {
				peerAddrs = append(peerAddrs, trim)
			}
		}
	}

	addr := ":" + strconv.Itoa(*port)

	// Create Raft node
	rn := &raft.RaftNode{ID: *id}
	rn.StartRaft()
	log.Printf("Raft node started with ID: %s", rn.ID)

	// Optionally create clients to peers (non-blocking)
	for _, p := range peerAddrs {
		go func(peerAddr string) {
			// try to connect with retries
			for i := 0; i < 5; i++ {
				pc, err := raft.NewPeerClient(peerAddr)
				if err == nil {
					// you may want to save pc into rn.peers map for use during elections
					log.Printf("Connected to peer %s", peerAddr)
					_ = pc // TODO: store
					return
				}
				log.Printf("failed to connect to peer %s: %v (retrying)", peerAddr, err)
				time.Sleep(500 * time.Millisecond)
			}
			log.Printf("giving up connecting to peer %s", peerAddr)
		}(p)
	}

	// Start listening
	lis, err := net.Listen("tcp", addr)
	if err != nil {
		log.Fatalf("failed to listen: %v", err)
	}

	grpcServer := grpc.NewServer()

	// Register KV service
	pb.RegisterKVServer(grpcServer, &server{raftNode: rn})

	// Register Raft service (so other nodes can call us)
	raftService := raft.NewRaftService(rn)
	raftpb.RegisterRaftServer(grpcServer, raftService)

	log.Printf("Node %s listening on %s (peers=%v)", *id, addr, peerAddrs)
	if err := grpcServer.Serve(lis); err != nil {
		log.Fatalf("failed to serve: %v", err)
	}
}

package main

import (
    "context"
    "log"
    "time"

    "google.golang.org/grpc"
    pb "github.com/siddharth-roy27/distributed-kv-store/proto/kv"
)

func main() {
    // Connect to the KV server
    conn, err := grpc.Dial("localhost:50051", grpc.WithInsecure())
    if err != nil {
        log.Fatalf("failed to connect: %v", err)
    }
    defer conn.Close()

    client := pb.NewKVClient(conn)

    // Example: Set a key-value pair
    setResp, err := client.Set(context.Background(), &pb.SetRequest{
        Key:   "name",
        Value: "Siddharth",
    })
    if err != nil {
        log.Fatalf("Set RPC failed: %v", err)
    }
    log.Printf("Set Success: %v", setResp.Success)

    // Wait a bit
    time.Sleep(1 * time.Second)

    // Example: Get the value for a key
    getResp, err := client.Get(context.Background(), &pb.GetRequest{
        Key: "name",
    })
    if err != nil {
        log.Fatalf("Get RPC failed: %v", err)
    }

    if getResp.Found {
        log.Printf("Get Response: key=%s, value=%s", "name", getResp.Value)
    } else {
        log.Printf("Key not found")
    }
}

package raft

import (
	"context"
	"log"

	"github.com/siddharth-roy27/distributed-kv-store/proto/raft"
)

// RaftService implements the generated gRPC server and delegates to RaftNode.
type RaftService struct {
	raftpb.UnimplementedRaftServer
	node *RaftNode
}

func NewRaftService(node *RaftNode) *RaftService {
	return &RaftService{node: node}
}

func (s *RaftService) RequestVote(ctx context.Context, req *raftpb.RequestVoteArgs) (*raftpb.RequestVoteReply, error) {
	// Map proto -> internal rpc types or call node method directly
	var reply raftpb.RequestVoteReply
	// Convert args to internal rpc types (simple mapping)
	args := &RequestVoteArgs{
		Term:         int(req.Term),
		CandidateID:  req.CandidateId,
		LastLogIndex: int(req.LastLogIndex),
		LastLogTerm:  int(req.LastLogTerm),
	}

	// Call internal implementation (which updates s.node state)
	internalReply := &RequestVoteReply{}
	s.node.RequestVote(args, internalReply)

	reply.Term = int32(internalReply.Term)
	reply.VoteGranted = internalReply.VoteGranted
	return &reply, nil
}

func (s *RaftService) AppendEntries(ctx context.Context, req *raftpb.AppendEntriesArgs) (*raftpb.AppendEntriesReply, error) {
	var reply raftpb.AppendEntriesReply

	// convert log entries
	entries := make([]LogEntry, 0, len(req.Entries))
	for _, e := range req.Entries {
		entries = append(entries, LogEntry{Term: int(e.Term), Command: e.Command})
	}

	args := &AppendEntriesArgs{
		Term:         int(req.Term),
		LeaderID:     req.LeaderId,
		PrevLogIndex: int(req.PrevLogIndex),
		PrevLogTerm:  int(req.PrevLogTerm),
		Entries:      entries,
		LeaderCommit: int(req.LeaderCommit),
	}

	internalReply := &AppendEntriesReply{}
	s.node.AppendEntries(args, internalReply)

	reply.Term = int32(internalReply.Term)
	reply.Success = internalReply.Success
	return &reply, nil
}

package raft

import (
	"context"
	"time"

	"google.golang.org/grpc"
	"github.com/siddharth-roy27/distributed-kv-store/proto/raft"
)

// PeerClient wraps a gRPC client to a peer
type PeerClient struct {
	id     string
	addr   string
	client raftpb.RaftClient
	conn   *grpc.ClientConn
}

func NewPeerClient(addr string) (*PeerClient, error) {
	conn, err := grpc.Dial(addr, grpc.WithInsecure(), grpc.WithBlock(), grpc.WithTimeout(2*time.Second))
	if err != nil {
		return nil, err
	}
	c := raftpb.NewRaftClient(conn)
	return &PeerClient{addr: addr, client: c, conn: conn}, nil
}

func (pc *PeerClient) Close() error {
	if pc.conn != nil {
		return pc.conn.Close()
	}
	return nil
}

func (pc *PeerClient) RequestVote(term int, candidateID string, lastLogIndex int, lastLogTerm int) (*raftpb.RequestVoteReply, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	req := &raftpb.RequestVoteArgs{
		Term:         int32(term),
		CandidateId:  candidateID,
		LastLogIndex: int32(lastLogIndex),
		LastLogTerm:  int32(lastLogTerm),
	}
	return pc.client.RequestVote(ctx, req)
}

func (pc *PeerClient) AppendEntries(term int, leaderID string, prevIndex, prevTerm int, entries []LogEntry, leaderCommit int) (*raftpb.AppendEntriesReply, error) {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	protoEntries := make([]*raftpb.LogEntry, 0, len(entries))
	for _, e := range entries {
		protoEntries = append(protoEntries, &raftpb.LogEntry{Term: int32(e.Term), Command: e.Command})
	}

	req := &raftpb.AppendEntriesArgs{
		Term:         int32(term),
		LeaderId:     leaderID,
		PrevLogIndex: int32(prevIndex),
		PrevLogTerm:  int32(prevTerm),
		Entries:      protoEntries,
		LeaderCommit: int32(leaderCommit),
	}
	return pc.client.AppendEntries(ctx, req)
}

