			}(p)
		}

		<-ticker.C
	}
}

// ProposeSet appends a Set command to the log and tries to replicate it to peers.
// Returns true if the entry was committed (majority replicated).
func (rn *RaftNode) ProposeSet(key, value string) bool {
	rn.mu.Lock()
	if rn.State != Leader {
		rn.mu.Unlock()
		return false
