	entry := LogEntry{Term: rn.CurrentTerm, Command: fmt.Sprintf("set:%s:%s", key, value)}
	rn.Log = append(rn.Log, entry)
	index := len(rn.Log) - 1
	rn.mu.Unlock()

	successes := 1
	var mu sync.Mutex
	var wg sync.WaitGroup

