	if rn.VotedFor == "" || rn.VotedFor == args.CandidateID {
		rn.VotedFor = args.CandidateID
		reply.VoteGranted = true
		rn.CurrentTerm = args.Term
	}
	reply.Term = int32(rn.CurrentTerm)
}

// Handle AppendEntries RPC (heartbeat + log replication)
